const formatDateValue = date => {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
};
const parseDateValue = value => {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(value || ''))) return null;
  const [y, m, d] = String(value).split('-').map(Number);
  const date = new Date(y, m - 1, d);
  return Number.isNaN(date.getTime()) ? null : date;
};
const DatePickerField = ({label, value, onChange, minimumDate}) => {
  const [open, setOpen] = useState(false);
  const initial = parseDateValue(value) || minimumDate || new Date();
  const [month, setMonth] = useState(new Date(initial.getFullYear(), initial.getMonth(), 1));
  const selected = parseDateValue(value);
  const min = minimumDate ? new Date(minimumDate.getFullYear(), minimumDate.getMonth(), minimumDate.getDate()) : null;
  useEffect(() => {
    const next = parseDateValue(value) || minimumDate || new Date();
    setMonth(new Date(next.getFullYear(), next.getMonth(), 1));
  }, [value]);
  const firstDay = new Date(month.getFullYear(), month.getMonth(), 1).getDay();
  const daysInMonth = new Date(month.getFullYear(), month.getMonth() + 1, 0).getDate();
  const cells = Array.from({length:firstDay + daysInMonth}, (_, i) => i < firstDay ? null : i - firstDay + 1);
  const choose = day => {
    const picked = new Date(month.getFullYear(), month.getMonth(), day);
    if (min && picked < min) return;
    onChange(formatDateValue(picked));
    setOpen(false);
  };
  return <View style={{flex:1}}>
    <Text style={s.label}>{label}</Text>
    <TouchableOpacity style={s.field} onPress={()=>setOpen(true)} accessibilityRole="button" accessibilityLabel={label}>
      <Text style={{fontSize:14,color:value?C.ink:'#A0A7B1'}}>{value || 'Select date'}</Text>
    </TouchableOpacity>
    <Modal visible={open} transparent animationType="fade" onRequestClose={()=>setOpen(false)}>
      <View style={s.modalShade}>
        <View style={s.datePickerCard}>
          <View style={s.rowBetween}>
            <TouchableOpacity onPress={()=>setMonth(new Date(month.getFullYear(),month.getMonth()-1,1))} disabled={!!min && new Date(month.getFullYear(),month.getMonth()-1,1) < new Date(min.getFullYear(),min.getMonth(),1)}>
              <Text style={s.dateNav}>‹</Text>
            </TouchableOpacity>
            <Text style={s.dateMonth}>{month.toLocaleDateString('en-IN',{month:'long',year:'numeric'})}</Text>
            <TouchableOpacity onPress={()=>setMonth(new Date(month.getFullYear(),month.getMonth()+1,1))}><Text style={s.dateNav}>›</Text></TouchableOpacity>
          </View>
          <View style={s.weekRow}>{['S','M','T','W','T','F','S'].map((d,i)=><Text key={i} style={s.weekDay}>{d}</Text>)}</View>
          <View style={s.calendarGrid}>{cells.map((day,i)=>{if(day===null)return <View key={i} style={s.calendarCell}/>;const picked=new Date(month.getFullYear(),month.getMonth(),day);const disabled=!!min&&picked<min;const active=!!selected&&formatDateValue(selected)===formatDateValue(picked);return <TouchableOpacity key={i} disabled={disabled} onPress={()=>choose(day)} style={[s.calendarCell,active&&s.calendarCellActive,disabled&&s.calendarCellDisabled]}><Text style={[s.calendarDay,active&&s.calendarDayActive,disabled&&s.calendarDayDisabled]}>{day}</Text></TouchableOpacity>;})}</View>
          <TouchableOpacity style={s.dateCancel} onPress={()=>setOpen(false)}><Text style={s.link}>Cancel</Text></TouchableOpacity>
        </View>
      </View>
    </Modal>
  </View>;
};
const TIME_HOURS = Array.from({length:24}, (_,i) => String(i).padStart(2,'0'));
const TIME_MINUTES = ['00','30'];
const WHEEL_ROW_HEIGHT = 58;
const WheelColumn = ({items, value, onChange, label}) => {
  const ref = useRef(null);
  const index = Math.max(0, items.indexOf(value));
  useEffect(() => {
    requestAnimationFrame(() => ref.current?.scrollTo({y:index * WHEEL_ROW_HEIGHT, animated:false}));
  }, [value]);
  const selectAtOffset = event => {
    const nextIndex = Math.max(0, Math.min(items.length - 1, Math.round(event.nativeEvent.contentOffset.y / WHEEL_ROW_HEIGHT)));
    const next = items[nextIndex];
    if (next && next !== value) onChange(next);
  };
  return <View style={s.wheelColumn}>
    <Text style={s.wheelLabel}>{label}</Text>
    <View style={s.wheelViewport}>
      <View pointerEvents="none" style={s.wheelSelection}/>
      <ScrollView
        ref={ref}
        showsVerticalScrollIndicator={false}
        snapToInterval={WHEEL_ROW_HEIGHT}
        decelerationRate="fast"
        bounces={false}
        contentContainerStyle={{paddingVertical:WHEEL_ROW_HEIGHT * 2}}
        onMomentumScrollEnd={selectAtOffset}
        onScrollEndDrag={event => {
          if (event.nativeEvent.contentOffset.y % WHEEL_ROW_HEIGHT !== 0) return;
          selectAtOffset(event);
        }}
      >
        {items.map(item => <View key={item} style={s.wheelItem}>
          <Text style={[s.wheelText,item===value&&s.wheelTextActive]}>{item}</Text>
        </View>)}
      </ScrollView>
    </View>
  </View>;
};
const TimePickerField = ({label, value, onChange}) => {
  const [open,setOpen]=useState(false);
  const initial = /^\\d{2}:\\d{2}$/.test(String(value||'')) ? String(value) : '10:00';
  const [hour,setHour]=useState(initial.slice(0,2));
  const [minute,setMinute]=useState(TIME_MINUTES.includes(initial.slice(3,5)) ? initial.slice(3,5) : '00');
  const openPicker=()=>{
    const current = /^\\d{2}:\\d{2}$/.test(String(value||'')) ? String(value) : '10:00';
    setHour(current.slice(0,2));
    setMinute(TIME_MINUTES.includes(current.slice(3,5)) ? current.slice(3,5) : '00');
    setOpen(true);
  };
  const done=()=>{ onChange(hour+':'+minute); setOpen(false); };
  return <View style={{flex:1}}>
    <Text style={s.label}>{label}</Text>
    <TouchableOpacity style={s.field} onPress={openPicker} accessibilityRole="button" accessibilityLabel={label}>
      <Text style={{fontSize:14,color:value?C.ink:'#A0A7B1'}}>{value || 'Select time'}</Text>
    </TouchableOpacity>
    <Modal visible={open} transparent animationType="slide" onRequestClose={()=>setOpen(false)}>
      <View style={s.modalShade}>
        <View style={s.timePickerSheet}>
          <View style={s.sheetHandle}/>
          <View style={s.rowBetween}>
            <View>
              <Text style={s.pageTitle}>Select time</Text>
              <Text style={s.smallMuted}>Scroll the hour and minute wheels</Text>
            </View>
            <TouchableOpacity onPress={()=>setOpen(false)} accessibilityRole="button"><Text style={s.link}>Cancel</Text></TouchableOpacity>
          </View>
          <View style={s.timeWheelArea}>
            <WheelColumn label="HOUR" items={TIME_HOURS} value={hour} onChange={setHour}/>
            <Text style={s.wheelColon}>:</Text>
            <WheelColumn label="MIN" items={TIME_MINUTES} value={minute} onChange={setMinute}/>
          </View>
          <View style={s.timePreview}>
            <Text style={s.timePreviewLabel}>SELECTED TIME</Text>
            <Text style={s.timePreviewValue}>{hour}:{minute}</Text>
          </View>
          <TouchableOpacity style={s.timeDoneButton} onPress={done} accessibilityRole="button">
            <Text style={s.timeDoneText}>Set {hour}:{minute}</Text>
          </TouchableOpacity>
        </View>
      </View>
    </Modal>
  </View>;
};
const DEFAULT_CITY = 'Udaipur';
const C = { ink: '#111827', muted: '#6B7280', orange: '#E56A3D', bg: '#F7F5F1', line: '#E7E2DA', white: '#FFFFFF', navy: '#151D2A', green: '#218765' };
const titleCaseType = value => {
  const text = String(value || '').trim().toLowerCase();
  return text ? `${text[0].toUpperCase()}${text.slice(1)}` : 'Other';
};
const normalizeVehicle = raw => {
  if (!raw || !raw.id || !raw.name) return null;
  const price = Number(raw.price ?? raw.pricePerDay);
  if (!Number.isFinite(price)) return null;
  const seats = Number(raw.seats);
  return {
    id: String(raw.id), vendorId: raw.vendorId || raw.ownerId || raw.resolvedVendorId || null, vendorName: raw.vendorName || raw.businessName || null, type: titleCaseType(raw.type), name: String(raw.name).trim(),
    detail: String(raw.detail ?? raw.subtitle ?? '').trim(), price,
    city: String(raw.city || '').trim(), seats: Number.isFinite(seats) && seats > 0 ? seats : null,
    transmission: raw.transmission ? String(raw.transmission) : null,
    fuel: raw.fuel ? String(raw.fuel) : null,
    emoji: raw.emoji || (String(raw.type).toLowerCase() === 'car' ? '🚘' : '🏍️'),
    color: raw.color || (String(raw.type).toLowerCase() === 'car' ? '#E7E9EF' : '#F2E9DA'),
    images: [...new Set([...(Array.isArray(raw.imageUrls) ? raw.imageUrls : []), ...(Array.isArray(raw.images) ? raw.images : []), raw.imageUrl, raw.photoUrl].filter(value => typeof value === 'string' && /^https?:\/\//i.test(value)))],
  };
};
const normalizeVehicleList = payload => {
  const list = [payload?.data, payload?.vehicles].find(Array.isArray) || [];
  return list.map(normalizeVehicle).filter(Boolean);
};
const isValidDateTimeInput = (dateValue, timeValue) => {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(dateValue || '')) || !/^\d{2}:\d{2}$/.test(String(timeValue || ''))) return false;
  const date = new Date(`${dateValue}T${timeValue}:00`);
  if (Number.isNaN(date.getTime())) return false;
  const [year, month, day] = dateValue.split('-').map(Number);
  const [hours, minutes] = timeValue.split(':').map(Number);
  return date.getFullYear() === year && date.getMonth() + 1 === month && date.getDate() === day && date.getHours() === hours && date.getMinutes() === minutes;
};
const uniqueSorted = values => [...new Set(values.filter(Boolean))].sort((a, b) => String(a).localeCompare(String(b)));
const money = n => `₹${Number(n || 0).toLocaleString('en-IN')}`;
const optimizeVehicleImageUrl = (url, width = 900) => {
  if (typeof url !== 'string' || !/^https?:\/\//i.test(url)) return url;
  try {
    const parsed = new URL(url);
    const match = parsed.pathname.match(/^(.*\/storage\/v1\/)object\/public\/(.+)$/);
    if (!match) return url;
    const query = new URLSearchParams(parsed.search);
    query.set('width', String(width));
    query.set('quality', '72');
    return `${parsed.origin}${match[1]}render/image/public/${match[2]}${query.toString() ? `?${query.toString()}` : ''}`;
  } catch {
    return url;
  }
};
const FastVehicleImage = ({ uri, style, fallback }) => {
  const [sourceUri, setSourceUri] = useState(() => optimizeVehicleImageUrl(uri));
  const [loading, setLoading] = useState(Boolean(uri));
  const [failed, setFailed] = useState(!uri);
  useEffect(() => {
    setSourceUri(optimizeVehicleImageUrl(uri));
    setLoading(Boolean(uri));
    setFailed(!uri);
  }, [uri]);
  if (!uri || failed) return fallback;
  return <View style={{position:'relative',alignSelf:'stretch'}}>
    <Image
      source={{uri:sourceUri, cache:'force-cache'}}
      style={style}
      resizeMode="cover"
      onLoadStart={()=>setLoading(true)}
      onLoadEnd={()=>setLoading(false)}
      onError={()=>{
        if(sourceUri !== uri){ setSourceUri(uri); setLoading(true); }
        else { setLoading(false); setFailed(true); }
      }}
    />
    {loading && <View style={{position:'absolute',left:0,right:0,top:0,bottom:0,alignItems:'center',justifyContent:'center'}}><ActivityIndicator size="small" color={C.orange}/></View>}
  </View>;
};
const friendlyError = (error, fallback) => {
  const status = Number(error?.status || 0);
  const raw = String(error?.message || '').toLowerCase();

  if (status === 401 || raw.includes('401') || raw.includes('unauthorized')) {
    return 'Your session has expired. Please sign in again.';
  }
  if (status === 404 || raw.includes('404') || raw.includes('not found')) {
    return fallback;
  }
  if (raw.includes('network request failed') || raw.includes('network error') || raw.includes('unreachable')) {
    return 'Please check your internet connection and try again.';
  }
  return fallback;
};
const Button = ({ title, onPress, ghost=false, disabled=false }) => <TouchableOpacity disabled={disabled} onPress={onPress} accessibilityRole="button" accessibilityState={{ disabled }} style={[s.button, ghost && s.ghostButton, disabled && { opacity: .45 }]}><Text style={[s.buttonText, ghost && s.ghostText]}>{title}</Text></TouchableOpacity>;
const Field = ({ label, value, onChangeText, placeholder, keyboardType }) => <View style={s.fieldWrap}><Text style={s.label}>{label}</Text><TextInput value={value} onChangeText={onChangeText} accessibilityLabel={label} placeholder={placeholder} placeholderTextColor="#A0A7B1" keyboardType={keyboardType} style={s.field}/></View>;
const PaymentStatus = ({message,state}) => {
  if(!message) return null;
  const failed=state==='failed';
  const submitted=state==='pending_verification';
  return <View style={[s.paymentStatus,failed&&s.paymentStatusError,submitted&&s.paymentStatusSuccess]}>
    <View style={[s.paymentStatusIcon,failed&&s.paymentStatusIconError,submitted&&s.paymentStatusIconSuccess]}><Text style={s.paymentStatusIconText}>{failed?'!':submitted?'✓':'i'}</Text></View>
    <View style={{flex:1,minWidth:0}}><Text style={s.paymentStatusTitle}>{failed?'Payment could not be started':submitted?'Payment submitted':'Next step'}</Text><Text style={s.paymentStatusText}>{message}</Text></View>
  </View>;
};

function FleetCheckoutScreen({cart,date,returnDate,onBack,onCreated}){
 const [pickup,setPickup]=useState(date||''); const [ret,setRet]=useState(returnDate||''); const [quote,setQuote]=useState(null); const [error,setError]=useState(''); const [busy,setBusy]=useState(false); const [delivery,setDelivery]=useState(true); const [address,setAddress]=useState(''); const [created,setCreated]=useState(false);
 const submit=async()=>{setError('');if(cart.length<2)return setError('Select at least two vehicles.');if(!pickup||!ret)return setError('Select pickup and return dates on Explore first.');const start=new Date(pickup+'T10:00:00'),end=new Date(ret+'T10:00:00');if(end<=start)return setError('Return must be after pickup.');if(delivery&&!address.trim())return setError('Add a delivery address.');setBusy(true);try{const payload={vehicleIds:cart.map(v=>String(v.id)),pickupAt:start.toISOString(),returnAt:end.toISOString(),delivery,address:address.trim(),deliveryLatitude:null,deliveryLongitude:null};const q=await rideOnApi.multiQuote(payload);const next=q?.quote||q?.data;if(!next?.total)throw new Error('The server did not return a valid fleet quote.');setQuote(next);}catch(e){setError(friendlyError(e,e?.message||'We could not quote the selected fleet. Please retry.'));}finally{setBusy(false);}};
 const checkout=async()=>{if(!quote)return submit();setBusy(true);setError('');try{const payload={vendorId:undefined,vehicleIds:cart.map(v=>String(v.id)),pickupAt:quote.startAt,returnAt:quote.endAt,delivery,address:address.trim(),deliveryLatitude:null,deliveryLongitude:null};delete payload.vendorId;const result=await rideOnApi.createFleetOrder(payload,`fleet-${Date.now()}-${Math.random().toString(36).slice(2,8)}`);onCreated?.(result.order||result.data);}catch(e){setError(friendlyError(e,e?.message||'We could not create the grouped booking. Please retry.'));}finally{setBusy(false);}};
 return <KeyboardAvoidingView style={{flex:1}} behavior={Platform.OS==='ios'?'padding':'height'}><ScrollView contentContainerStyle={s.page} keyboardShouldPersistTaps="handled"><Header title="RideOn Fleet checkout"/><Text style={s.pageTitle}>Book multiple vehicles</Text><Text style={s.pageSub}>One RideOn checkout for the selected bikes and scooters.</Text>{cart.map(v=><View key={v.id} style={s.compactVehicle}><Text style={{fontSize:28}}>{v.type==='Scooter'?'🛵':'🏍️'}</Text><View style={{flex:1}}><Text style={s.cardTitle}>{v.name}</Text><Text style={s.smallMuted}>{v.type} · {money(v.price)} / day</Text></View></View>)}<View style={s.scheduleGrid}><Field label="PICKUP DATE" value={pickup} onChangeText={setPickup} placeholder="YYYY-MM-DD"/><Field label="RETURN DATE" value={ret} onChangeText={setRet} placeholder="YYYY-MM-DD"/></View><DeliverySelector value={delivery} onChange={setDelivery} address={address} onEditAddress={()=>{}} onSelectSaved={()=>{}}/><Field label="DELIVERY ADDRESS" value={address} onChangeText={setAddress} placeholder="Your RideOn delivery address"/>{error&&<View style={s.errorBox}><Text style={s.errorText}>{error}</Text></View>}{quote&&<View style={s.summary}><Text style={s.summaryKicker}>RIDEON FLEET QUOTE</Text><View style={s.summaryLine}><Text style={s.summaryLabel}>Vehicles</Text><Text style={s.summaryValue}>{quote.items.length}</Text></View><View style={s.summaryLine}><Text style={s.summaryLabel}>Rental</Text><Text style={s.summaryValue}>{money(quote.rentalSubtotal)}</Text></View><View style={s.summaryLine}><Text style={s.summaryLabel}>Delivery</Text><Text style={s.summaryValue}>{money(quote.deliveryFee)}</Text></View><View style={s.summaryLine}><Text style={s.summaryLabel}>Platform fee</Text><Text style={s.summaryValue}>{money(quote.platformFee)}</Text></View><View style={s.summaryLine}><Text style={s.summaryLabel}>Security deposit</Text><Text style={s.summaryValue}>{money(quote.securityDeposit)}</Text></View><View style={s.divider}/><View style={s.summaryTotal}><Text style={s.summaryTotalLabel}>Total payable</Text><Text style={s.priceLarge}>{money(quote.total)}</Text></View></View>}<Button title={busy?(quote?'Creating booking…':'Checking availability…'):(quote?'Create grouped booking →':'Check availability & quote →')} disabled={busy} onPress={quote?checkout:submit}/><Button title="Back" ghost disabled={busy} onPress={onBack}/></ScrollView></KeyboardAvoidingView>;
}
function FleetConfirmationScreen({order,onTrips,onExplore}){return <ScrollView contentContainerStyle={s.page}><Header title="Booking confirmed"/><View style={s.empty}><Text style={s.emptyEmoji}>✓</Text><Text style={s.pageTitle}>RideOn fleet order created</Text><Text style={s.pageSub}>{order?.items?.length||0} vehicles are grouped under one order.</Text><Text style={s.cardTitle}>Order {order?.id}</Text><Text style={s.priceLarge}>{money(order?.total)}</Text><Button title="View Trips" onPress={onTrips}/><Button title="Back to Fleet" ghost onPress={onExplore}/></View></ScrollView>;}
