 const categoryLabel=type=>type==='All'?'All rides':type;
 const waitForPaymentConfirmation=async(bookingId)=>{
   const delays=[900,1200,1600,2200,3000,4000,5000];
   for(const delay of delays){
     await new Promise(resolve=>setTimeout(resolve,delay));
     const result=await rideOnApi.getBooking(bookingId);
     const booking=result?.booking||result?.data;
     const status=String(booking?.paymentStatus||'').toLowerCase();
     const trip=normalizeTrip(booking);
     setTrips(current=>current.some(t=>String(t.id)===String(trip.id))?current.map(t=>String(t.id)===String(trip.id)?{...t,...trip}:t):[trip,...current]);
     setSelectedBooking(trip);
     if(status==='paid'||status==='failed'||status==='refunded') return {booking:trip,status};
   }
   return {booking:null,status:'pending'};
 };
 const refreshBookingQuote=async()=>{
   if(bookingBusy||paymentBusy)return;
   setBookingError('');
   if(!selected)return setBookingError('Choose a vehicle before continuing.');
   if(!bookingWindow)return setBookingError('Complete valid pickup and return date/time.');
   if(bookingWindow.endMs<=bookingWindow.startMs)return setBookingError('Return must be after pickup.');
   if(bookingWindow.startMs<Date.now())return setBookingError('Pickup cannot be in the past.');
   if(delivery&&!address.trim())return setBookingError('Add a delivery address.');
   setBookingBusy(true);
   try{
     const availabilityResult=await rideOnApi.availability(selected.id,{startAt:bookingWindow.startAt,endAt:bookingWindow.endAt});
     setAvailability(availabilityResult);
     if(!availabilityResult?.available){
       setQuote(null);
       setBookingError('This vehicle is no longer available for the selected dates. Please choose different dates.');
       return;
     }
     const result=await rideOnApi.quote({vehicleId:selected.id,startAt:bookingWindow.startAt,endAt:bookingWindow.endAt,delivery});
     const nextQuote=result?.quote||result?.data;
     if(!nextQuote?.total||Number(nextQuote.total)<=0)throw new Error('The server did not return a valid quote.');
     setQuote(nextQuote);setScreen('review');
   }catch(error){
     if(error?.code==='VEHICLE_UNAVAILABLE')setBookingError('This vehicle is no longer available for the selected dates. Please choose different dates.');
     else setBookingError(friendlyError(error, 'We could not get a server quote right now. Please try again.'));
   }finally{setBookingBusy(false);}
 };
 const finishBooking=async()=>{
   if(bookingBusy||paymentBusy)return;
   setBookingError('');setPaymentError('');
   if(!selected)return setBookingError('Choose a vehicle before continuing.');
   const mobile=phone.replace(/\D/g,'');
   if(name.trim().length<2)return setBookingError('Enter your full name.');
   if(mobile.length<10)return setBookingError('Enter a valid mobile number.');
   if(!bookingWindow)return setBookingError('Complete valid pickup and return date/time.');
   if(bookingWindow.endMs<=bookingWindow.startMs)return setBookingError('Return must be after pickup.');
   if(bookingWindow.startMs<Date.now())return setBookingError('Pickup cannot be in the past.');
   if(delivery&&!address.trim())return setBookingError('Add a delivery address or turn off doorstep delivery.');
   if(!quote?.total||Number(quote.total)<=0)return setBookingError('Refresh the server quote before payment.');
   setBookingBusy(true);
   let trip;
   try{
     const availabilityResult=await rideOnApi.availability(selected.id,{startAt:bookingWindow.startAt,endAt:bookingWindow.endAt});
     setAvailability(availabilityResult);
     if(!availabilityResult?.available){
       setQuote(null);setBookingError('This vehicle is no longer available for the selected dates. Please choose different dates.');setScreen('booking');return;
     }
     const idempotencyKey=`rideon:${selected.id}:${bookingWindow.startAt}:${bookingWindow.endAt}:${mobile}`;
     const result=await rideOnApi.createBooking({vehicleId:selected.id,customerName:name.trim(),phone:mobile,startAt:bookingWindow.startAt,endAt:bookingWindow.endAt,delivery,address:delivery?address.trim():'Self pickup',deliveryLatitude:delivery?deliveryLocation?.latitude:null,deliveryLongitude:delivery?deliveryLocation?.longitude:null},idempotencyKey);
     const booking=result?.booking||result?.data;
     if(!booking?.bookingId)throw new Error('Booking request was not acknowledged by the server.');
     if(delivery&&deliveryLocation?.latitude!=null&&deliveryLocation?.longitude!=null){try{const routed=await rideOnApi.updateBookingRoute(booking.bookingId);if(routed?.booking) {const routedTrip=normalizeTrip(routed.booking);setSelectedBooking(routedTrip);setSelected(routedTrip);mergeTrips([routedTrip]);}}catch(routeError){console.warn('[RideOn] booking route refresh failed',routeError?.code||routeError?.message||routeError);}}
     trip=normalizeTrip(booking);
     setTrips(old=>old.some(t=>String(t.id)===String(trip.id))?old:[trip,...old]);
     setSelectedBooking(trip);setQuote(booking.pricing||quote);
   }catch(error){
     if(error?.code==='VEHICLE_UNAVAILABLE'){setQuote(null);setBookingError('This vehicle is no longer available for the selected dates. Please choose different dates.');setScreen('booking');}
     else setBookingError(friendlyError(error, 'We could not create your booking request right now. Please try again.'));
     return;
   }finally{setBookingBusy(false);}
   setPaymentBusy(true);
   try{
     if(!paymentCapabilities){const caps=await rideOnApi.getPaymentCapabilities();setPaymentCapabilities(caps?.payment||caps);}
     const orderResult=await rideOnApi.createPaymentOrder({bookingId:trip.id,idempotencyKey:`payment:${trip.id}`});
     const payment=orderResult?.payment;
     if(!payment?.id||(!payment?.amountPaise&&!payment?.amount))throw new Error('Payment order was not created by the server.');
     setPaymentRecord(payment);setPaymentState(String(payment.status||'pending').toLowerCase());
     setPaymentError(payment.paymentUrl?'':'Payment checkout is not available from the current provider configuration.');
   }catch(error){
     setPaymentRecord(null);setPaymentState('blocked');
     if(error?.code==='PAYMENT_PROVIDER_CONFIGURATION_REQUIRED'||error?.code==='PAYMENT_NOT_CONFIGURED')setPaymentError('Online UPI payment is not available yet. Your booking is saved, but it has not been paid. Razorpay checkout must be configured before payment can be completed.');
     else setPaymentError(friendlyError(error, 'We could not start payment for this booking. Your booking is saved and remains unpaid.'));
   }finally{setPaymentBusy(false);}
   setScreen('payment');
 };
 const startPayment=async()=>{
   if(paymentBusy||!selectedBooking?.id)return;
   setPaymentBusy(true);setPaymentError('');
   try{
     let payment=paymentRecord;
     if(!payment){
       const orderResult=await rideOnApi.createPaymentOrder({bookingId:selectedBooking.id,idempotencyKey:`payment:${selectedBooking.id}`});
       payment=orderResult?.payment;
       if(!payment?.id||(!payment?.amountPaise&&!payment?.amount))throw new Error('Payment order was not created by the server.');
       setPaymentRecord(payment);
     }
     setPaymentState(String(payment.status||'pending').toLowerCase());
     if(payment.paymentUrl){
       const canOpen=await Linking.canOpenURL(payment.paymentUrl);
       if(!canOpen){setPaymentState('failed');setPaymentError('The payment checkout could not be opened on this device. Choose another payment method or try again.');return;}
       await Linking.openURL(payment.paymentUrl);
       setPaymentError('Complete payment in the provider checkout. RideOn will confirm the result from the server when you return.');
     }else {
       setPaymentState('blocked');
       setPaymentError('Online UPI checkout is not available for the configured provider. Your booking remains unpaid.');
     }
   }catch(error){
     if(error?.code==='PAYMENT_PROVIDER_CONFIGURATION_REQUIRED'||error?.code==='PAYMENT_NOT_CONFIGURED')setPaymentError('Online payment is not available yet. Your booking remains unpaid until Razorpay checkout is enabled.');
     else setPaymentError(friendlyError(error, 'We could not start the payment. Your booking is still safe. Please try again.'));
     setPaymentState('blocked');
   }finally{setPaymentBusy(false);}
 };
 const retryPayment=()=>{setPaymentError('');setPaymentState(null);startPayment();};
 useEffect(()=>{
   if((screen!=='payment'||!selectedBooking?.id)&&(screen!=='fleetPayment'||!fleetCheckoutOrder?.id)) return;
   const subscription=AppState.addEventListener('change', state=>{
     if(state==='active'){if(screen==='payment')refreshPaymentStatus();if(screen==='fleetPayment')refreshFleetPayment();}
   });
   return()=>subscription.remove();
 },[screen,selectedBooking?.id,fleetCheckoutOrder?.id]);

 const refreshPaymentStatus=async()=>{
   if(!selectedBooking?.id||paymentBusy)return;
   setPaymentBusy(true);setPaymentError('');
   try{
     const latest=await rideOnApi.getBooking(selectedBooking.id);
     const latestTrip=normalizeTrip(latest);
     mergeTrips([latestTrip]);setSelectedBooking(latestTrip);
     const status=String(latestTrip.paymentStatus||'').toLowerCase();
     if(status==='paid'){setPaymentState('paid');setScreen('success');}
     else if(status==='failed'){setPaymentState('failed');setPaymentError('Payment was not confirmed. You can safely retry.');}
     else {setPaymentState(status||'pending');setPaymentError('Payment is still pending provider confirmation.');}
   }catch(error){setPaymentError(friendlyError(error,'We could not refresh payment status. Please try again.'));}
   finally{setPaymentBusy(false);}
 };
 const refreshFleetPayment=async()=>{
   if(!fleetCheckoutOrder?.id||fleetLoading)return;
   setFleetLoading(true);
   try{
     const latest=await rideOnApi.getFleetOrder(fleetCheckoutOrder.id);
     const order=latest?.order||latest?.data||latest;
     if(order){setFleetCheckoutOrder(order);setFleetPayment(prev=>({...prev,status:order.paymentStatus||prev?.status||'pending'}));if(String(order.paymentStatus||'').toLowerCase()==='paid')setToast('Fleet payment confirmed.');}
   }catch(error){setFleetPaymentError(friendlyError(error,'We could not refresh fleet payment status. Please try again.'));}
   finally{setFleetLoading(false);}
 };
 useEffect(()=>{
   const subscription=Linking.addEventListener('url', event=>{
     if(event?.url?.startsWith('rideon://payment-return')){if(screen==='payment'&&selectedBooking?.id)refreshPaymentStatus();if(screen==='fleetPayment'&&fleetCheckoutOrder?.id)refreshFleetPayment();}
   });
   return()=>subscription.remove();
 },[screen,selectedBooking?.id,fleetCheckoutOrder?.id]);
 useEffect(()=>{const handler=()=>{if(screen==='payment'){setScreen('review');return true;}if(screen==='success'){setScreen('');setSelected(null);setSelectedBooking(null);setPage('Trips');return true;}if(screen){setScreen('');return true;}return false;};const sub=BackHandler.addEventListener('hardwareBackPress',handler);return()=>sub.remove();},[screen]);
 const closeFlow=()=>{setScreen('');setSelected(null);setSelectedBooking(null);setBookingError('');setPaymentError('');setPaymentState(null);setPaymentRecord(null);setPaymentReferenceDraft('');setQuote(null);setDeliveryLocation(null);};
 const Header=({title,back=true})=><View style={s.innerHeader}>{back&&<TouchableOpacity onPress={()=>screen?closeFlow():setPage('Explore')}><Text style={s.back}>‹</Text></TouchableOpacity>}<Text style={s.innerTitle}>{title}</Text><View style={{width:24}}/></View>;
 const VehicleCard=({v})=><View style={s.vehicleCard}><View style={s.vehicleArt}>{v.images?.length?<FastVehicleImage uri={v.images[0]} style={s.vehicleImage} fallback={<Text style={s.vehicleEmoji}>{v.emoji}</Text>}/>:<Text style={s.vehicleEmoji}>{v.emoji}</Text>}<Text style={s.artWord}>{v.type.toUpperCase()} · RIDEON FLEET</Text></View><View style={s.vehicleRow}><View style={{flex:1,minWidth:0}}><Text style={s.vehicleName} numberOfLines={1}>{v.name}</Text><Text style={s.smallMuted} numberOfLines={2}>{v.detail||'Vehicle specifications supplied by the fleet API.'}</Text></View><View style={{alignItems:'flex-end',marginLeft:10}}><Text style={s.price}>{money(v.price)}</Text><Text style={s.smallMuted}>/ day</Text></View></View><View style={s.vehicleSpecsRow}>{[v.transmission,v.seats?`${v.seats} seats`:null,v.fuel].filter(Boolean).map(spec=><Text key={spec} style={s.vehicleSpec}>{spec}</Text>)}</View><View style={s.cardBottom}><TouchableOpacity accessibilityRole="button" onPress={()=>{setSelected(v);setScreen('vehicle')}}><Text style={s.link}>View details →</Text></TouchableOpacity><TouchableOpacity accessibilityRole="button" onPress={()=>openBooking(v)}><Text style={s.bookLink}>Book now →</Text></TouchableOpacity></View></View>

const normalizeStatus=(value)=>{const v=String(value||'').toLowerCase();if(['cancelled','canceled'].includes(v))return 'Cancelled';if(v==='rejected')return 'Rejected';if(v==='completed')return 'Completed';if(v==='in_progress'||v==='in-progress')return 'In progress';if(v==='confirmed')return 'Confirmed';if(v==='requested')return 'Requested';return 'Other';};
 const tripCategory=(value)=>{const v=String(value||'').toLowerCase();if(['cancelled','canceled','rejected'].includes(v))return 'Cancelled';if(v==='in_progress'||v==='in-progress')return 'Active';if(v==='completed')return 'Completed';return 'Upcoming';};
 const tripDisplayStatus=(value)=>{const v=String(value||'').toLowerCase();if(v==='requested')return 'Pending confirmation';if(v==='confirmed')return 'Confirmed';if(v==='in_progress'||v==='in-progress')return 'Active rental';if(v==='completed')return 'Completed';if(v==='rejected')return 'Booking not accepted';if(['cancelled','canceled'].includes(v))return 'Cancelled';return 'Unknown';};
 const normalizeTrip=(raw)=>{const x=raw?.booking||raw?.data||raw||{};const vehicle=x.vehicle||{};const pricing=x.pricing||{};const id=x.bookingId||x.id;return {id,vehicle:x.vehicleName||vehicle.name||'RideOn vehicle',vehicleId:x.vehicleId||vehicle.id||null,vehicleType:x.vehicleType||vehicle.type||null,status:x.status||'unknown',statusLabel:normalizeStatus(x.status),displayStatus:tripDisplayStatus(x.status),category:tripCategory(x.status),paymentStatus:x.paymentStatus||'unknown',pickupAt:x.startAt||x.startDate||null,returnAt:x.endAt||x.returnDate||null,address:x.address||x.deliveryAddress||'',delivery:x.deliveryRequired??x.delivery??true,pricing,total:Number(x.totalPrice??x.total??pricing.total??0),instructions:x.instructions||x.bookingInstructions||'',cancellationFee:Number(x.cancellationFee||0),refundAmount:Number(x.refundAmount||0),cancellationReason:x.cancellationReason||x.rejectionReason||'',securityDepositStatus:x.securityDepositStatus||null,securityDepositRefundable:Number(x.securityDepositRefundable||0),securityDepositDeduction:Number(x.securityDepositDeduction||0),securityDepositReason:x.securityDepositReason||'',securityDepositEvidence:x.securityDepositEvidence||'',deliveryStatus:x.deliveryStatus||'scheduled',deliveryStartedAt:x.deliveryStartedAt||null,deliveredAt:x.deliveredAt||null,deliveryLatitude:x.deliveryLatitude??null,deliveryLongitude:x.deliveryLongitude??null,routeDistanceMeters:Number(x.routeDistanceMeters||0)||null,routeDurationSeconds:Number(x.routeDurationSeconds||0)||null,raw:x};};
 const setReviewErrorSafe=value=>setReviewError(value||'');
 const refreshReviewStatuses=async(items=trips)=>{const completed=items.filter(t=>String(t?.status||'').toLowerCase()==='completed'&&t.id);if(!completed.length)return;const entries=await Promise.all(completed.map(async t=>{try{return [String(t.id),await rideOnApi.getReviewStatus(t.id)];}catch(error){return [String(t.id),{error}];}}));setReviewStatusByBooking(old=>({...old,...Object.fromEntries(entries)}));};
 const openReviewForBooking=async(booking)=>{const id=booking?.id||booking?.bookingId;if(!id)return;setReviewErrorSafe('');setReviewBusy(true);try{const status=await rideOnApi.getReviewStatus(id);const data=status?.data;if(!data?.eligible){setToast('Reviews become available after the rental is completed.');return;}const existing=data?.review;if(existing){const editable=existing.createdAt&&Date.now()-new Date(existing.createdAt).getTime()<=30*86400000;if(!editable){setToast('This review is now read-only.');return;}setReviewEditing(true);setReviewBooking({...booking,id});setReviewOpen(true);setReviewStatusByBooking(old=>({...old,[String(id)]:data}));return;}setReviewEditing(false);setReviewBooking({...booking,id});setReviewOpen(true);setReviewStatusByBooking(old=>({...old,[String(id)]:data}));}catch(error){setToast(friendlyError(error,'We could not check review eligibility right now. Please retry.'));}finally{setReviewBusy(false);}};
 const submitCustomerReview=async payload=>{if(!reviewBooking?.id||reviewBusy)return;setReviewBusy(true);setReviewErrorSafe('');try{const result=reviewEditing?await rideOnApi.updateReview(reviewStatusByBooking[String(reviewBooking.id)]?.review?.id,payload):await rideOnApi.createCustomerReview(reviewBooking.id,payload);setReviewOpen(false);setReviewBooking(null);setReviewEditing(false);setReviewStatusByBooking(old=>({...old,[String(reviewBooking.id)]:{eligible:true,review:result.review,reviewType:'customer_to_vendor'}}));setToast(reviewEditing?'Your review was updated.':'Thanks — your review has been published.');}catch(error){if(error?.code==='REVIEW_ALREADY_EXISTS'){setReviewOpen(false);setToast('This booking has already been reviewed.');}else setReviewErrorSafe(friendlyError(error,'We could not save your review right now. Please retry.'));}finally{setReviewBusy(false);}};
 const openVehicleReview=async vehicle=>{const candidate=trips.find(t=>String(t.vehicleId)===String(vehicle?.id)&&String(t.status).toLowerCase()==='completed');if(!candidate){setToast('Complete a rental with this vehicle before reviewing it.');return;}await openReviewForBooking(candidate);};
 const mergeTrips=(incoming)=>{setTrips(current=>{const map=new Map(current.filter(t=>t?.id).map(t=>[String(t.id),t]));incoming.filter(t=>t?.id).forEach(t=>map.set(String(t.id),{...(map.get(String(t.id))||{}),...t}));return [...map.values()];});};
 const loadTripDetail=async(id)=>{if(!id||tripActionBusy)return;setTripActionError('');setTripDetailLoading(true);setTripActionBusy(true);try{const result=await rideOnApi.getBooking(id);const detail=normalizeTrip(result);mergeTrips([detail]);setSelectedBooking(detail);setSelected(detail);}catch(error){setTripActionError(friendlyError(error, 'We could not load this trip right now. Please try again.'));}finally{setTripActionBusy(false);setTripDetailLoading(false);}};
 const openCancellation=async()=>{const id=selectedBooking?.id||selected?.id;if(!id||tripActionBusy)return;setTripActionError('');setTripActionBusy(true);try{const result=await rideOnApi.getCancellationPreview(id);setCancellationPreview(result?.cancellation||result);setAccountConfirm({type:'cancelBooking'});}catch(error){setTripActionError(friendlyError(error,'This booking can no longer be cancelled. Please refresh and try again.'));}finally{setTripActionBusy(false);}};
 const cancelTrip=async()=>{const id=selectedBooking?.id||selected?.id;if(!id||tripActionBusy)return;setTripActionError('');setTripActionBusy(true);try{const result=await rideOnApi.cancelBooking(id,{reason:'customer_cancelled'});const updated=normalizeTrip(result);mergeTrips([updated]);setSelectedBooking(updated);setSelected(updated);setAccountConfirm(null);setCancellationPreview(result?.cancellation||null);setToast(result?.refund?.status==='refund_pending'?'Booking cancelled. Refund is pending provider confirmation.':'Booking cancelled successfully.');}catch(error){setTripActionError(friendlyError(error,'We could not cancel this trip right now. Please try again.'));}finally{setTripActionBusy(false);}};
